fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2, but handle smaller n gracefully.
    let mut fibs: Vec<i32> = Vec::with_capacity(n);
    if n >= 1 {
        fibs.push(0);
    }
    if n >= 2 {
        fibs.push(1);
    }
    for i in 2..n {
        // According to the problem statement, we are guaranteed
        // that fibonacci numbers up to index n-1 fit in i32.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }
    fibs
}

